<script setup>
import { onMounted, ref } from 'vue'; import { getTasks } from '../../api/wms'
const list=ref([]); const names={PICKING:'拣货',PUTAWAY:'上架',COUNTING:'盘点',REPLENISHMENT:'补货',RECEIVING:'收货',PACKING:'复核打包'}; const status={WAITING:'待领取',IN_PROGRESS:'作业中',EXCEPTION:'异常',COMPLETED:'已完成'}; onMounted(async()=>list.value=await getTasks())
</script>
<template><div><div class="page-head"><div><h1>任务调度</h1><p>把入库、拣选、补货和盘点任务分配到现场人员</p></div><div class="page-actions"><button class="btn">批量分配</button><button class="btn primary">新建任务</button></div></div><div class="filters"><input class="filter-input" placeholder="任务号、人员或 SKU"><select class="filter-select"><option>全部任务类型</option><option>拣货</option><option>补货</option></select><select class="filter-select"><option>全部状态</option><option>待领取</option><option>作业中</option></select><span class="filter-spacer"></span><span class="result-count">{{list.length}} 项任务 · 3 项高优先级</span></div>
<table class="data-table"><thead><tr><th>任务编号</th><th>类型 / 优先级</th><th>起始库位</th><th>目标库位</th><th>商品</th><th>数量进度</th><th>执行人</th><th>时限</th><th>状态</th></tr></thead><tbody><tr v-for="i in list" :key="i.id"><td class="mono">{{i.taskNo}}</td><td><strong>{{names[i.type]}}</strong><small>{{i.priority==='URGENT'?'紧急':i.priority==='HIGH'?'高':'普通'}}</small></td><td class="mono">{{i.sourceLocation}}</td><td class="mono">{{i.targetLocation||'—'}}</td><td><strong>{{i.productName}}</strong><small>{{i.skuCode}}</small></td><td><div class="progress-track"><i :style="{width:`${i.completedQty/i.plannedQty*100}%`}"></i></div><small>{{i.completedQty}} / {{i.plannedQty}}</small></td><td>{{i.assignee}}</td><td>{{i.dueAt.slice(11,16)}}</td><td><span class="status" :class="i.status==='EXCEPTION'?'red':i.status==='COMPLETED'?'green':i.status==='IN_PROGRESS'?'amber':''">{{status[i.status]}}</span></td></tr></tbody></table></div></template>
